"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9],{4009:(a,e,i)=>{i.r(e),i.d(e,{grammarTk:()=>n});let n={1:{title:"Esasy EID s\xf6z tertibi",explanation:"Hyta\xfd dilinde s\xf6z tertibi \xabE\xfde + Işlik + Doldurgy\xe7\xbb g\xf6rn\xfcşinde, iňlis we t\xfcrkmen dillerine meňzeş.",examples:["Men i\xfd\xfd\xe4rin.","Ol suw i\xe7\xfd\xe4r.","Ol oka\xfdar."]},2:{title:"At s\xf6zleri 是 bilen baglanyşdyrmak",explanation:"是 (sh\xec) iki at s\xf6z\xfcni baglanyşdyr\xfdar, t\xfcrkmen dilind\xe4ki \xabbolmak\xbb \xfdaly. A-ny B bilen deňeşdir\xfd\xe4r.",examples:["Men talyp.","Ol mugallym.","Bu meniň kitabym."]},3:{title:"Sypat bilen 很 ulanmak",explanation:"Hyta\xfd dilinde sypatlar g\xf6ni habar bolup bil\xfd\xe4r. 很 k\xf6plen\xe7 sypatyň \xf6ň\xfcnde go\xfdul\xfdar, hatda \xabgaty\xbb manysynda ulanylmasa-da.",examples:["Men gowy.","Bu g\xfcn sowuk.","Hyta\xfd nahary tagamly."]},4:{title:"有 bilen e\xfde\xe7ilik",explanation:"有 (yǒu) e\xfde\xe7iligi aňlad\xfdar, t\xfcrkmen dilind\xe4ki \xabbar\xbb \xfdaly.",examples:["Meniň bir dostum bar.","Onuň iki \xe7agasy bar.","Seniň puluň barmy?"]},5:{title:"有 bilen barlygy aňlatmak",explanation:"有 bir \xfderde bir zadyň barlygyny hem aňladyp bil\xfd\xe4r — \xabbar\xbb manysynda.",examples:["Stoluň \xfcst\xfcnde bir kitap bar.","Mekdepde k\xf6p talyp bar."]},6:{title:"是…的 bilen jikme-jikligi nygtamak",explanation:"Belli bir hereketiň ha\xe7an, nirede, n\xe4dip \xfda-da kim tarapyndan edilendigini nygtamak \xfc\xe7in ulanyl\xfdar.",examples:["Sen ha\xe7an geldiň?","Men u\xe7ar bilen geldim.","Ol hyta\xfd dilini Pekinde \xf6wrendi."]},7:{title:"和 bilen at s\xf6zleri baglanyşdyrmak",explanation:"和 (h\xe9) iki at s\xf6z\xfcni baglanyşdyr\xfdar, \xabwe\xbb \xfdaly. S\xf6zlemleri \xfda-da işlikleri baglanyşdyrmak \xfc\xe7in ulanylma\xfdar.",examples:["men we sen","Kaka bilen eje ikisi-de mugallym.","Almalar we suw ikisi-de stoluň \xfcst\xfcnde."]},8:{title:"的 bilen at s\xf6zleri \xfc\xfdtgetmek",explanation:"的 (de) e\xfde\xe7iligi belle\xfd\xe4r \xfda-da at s\xf6z\xfcni sypat, s\xf6z d\xfcz\xfcmi bilen \xfc\xfdtged\xfd\xe4r.",examples:["meniň kitabym","owadan gyz","Onuň \xfdazan harplary gaty owadan."]},9:{title:"不 bilen ink\xe4r etmek",explanation:"不 (b\xf9) h\xe4zirki \xfda-da geljekki işlikleri we sypatlary ink\xe4r ed\xfd\xe4r. Ge\xe7mişd\xe4ki hereketleri ink\xe4r etme\xfd\xe4r.",examples:["Men kofe i\xe7me\xfd\xe4rin.","Ol şat d\xe4l.","Men hyta\xfdly d\xe4l."]},10:{title:"有-ny 没 bilen ink\xe4r etmek",explanation:"有 hemişe 没 bilen ink\xe4r edil\xfd\xe4r, hi\xe7 ha\xe7an 不 bilen d\xe4l. 没有 \xab\xfdok\xbb manysyny ber\xfd\xe4r.",examples:["Meniň pulum \xfdok.","Bu \xfderde hi\xe7 kim \xfdok."]},11:{title:"没有 bilen ge\xe7mişi ink\xe4r etmek",explanation:"没(有) tamamlanan hereketleri ink\xe4r ed\xfd\xe4r — bir zat ge\xe7mişde bolmady.",examples:["Men gitmedim.","Ol ertirlik i\xfdmedi.","Ol sapaga gelmedi."]},12:{title:"不太 bilen 'k\xe4n d\xe4l'",explanation:"不太 ink\xe4ri \xfdumşad\xfdar — \xabk\xe4n d\xe4l\xbb \xfda-da \xabo di\xfden d\xe4l\xbb.",examples:["Men o di\xfden halama\xfdaryn.","Ol k\xe4n şat d\xe4l."]},13:{title:"不…了 bilen 'indi…d\xe4l'",explanation:"\xddagda\xfdyň \xfc\xfdtgemegini aňlad\xfdar — bir zat indi be\xfdle d\xe4l \xfda-da indi bolmaz.",examples:["Men indi i\xfdjek d\xe4l.","Ol indi arak i\xe7me\xfd\xe4r."]},14:{title:"吗 bilen hawa/\xfdok soraglary",explanation:"Islendik s\xf6zlemiň soňuna 吗 (ma) goşuň, hawa/\xfdok soragyna \xf6w\xfcrmek \xfc\xe7in.",examples:["Sen mugallymmy?","Sen hyta\xfd naharyny hala\xfdarmy?","Ol geldimi?"]},15:{title:"什么 bilen 'n\xe4me' soramak",explanation:"什么 (sh\xe9nme) \xabn\xe4me\xbb manysyny ber\xfd\xe4r. Jogabyň \xfderinde dur\xfdar.",examples:["Seniň adyň n\xe4me?","N\xe4me i\xfdmek isle\xfd\xe4rsiň?","Bu n\xe4me?"]},16:{title:"谁 bilen 'kim' soramak",explanation:"谁 (sh\xe9i) \xabkim\xbb manysyny ber\xfd\xe4r. S\xf6zlemd\xe4ki adamy \xe7alyş\xfdar.",examples:["Ol kim?","Kim geldi?"]},17:{title:"哪儿/哪里 bilen 'nirede' soramak",explanation:"哪儿 (nǎr) \xfda-da 哪里 (nǎlǐ) \xabnirede\xbb manysyny ber\xfd\xe4r.",examples:["Sen nirede \xfdaşa\xfdarsyň?","Hassahana nirede?"]},18:{title:"什么时候 bilen 'ha\xe7an' soramak",explanation:"什么时候 (sh\xe9nme sh\xedh\xf2u) \xabha\xe7an\xbb manysyny ber\xfd\xe4r.",examples:["Sen ha\xe7an gel\xfd\xe4rsiň?","Biz ha\xe7an i\xfd\xfd\xe4ris?"]},19:{title:"怎么 bilen 'n\xe4dip' soramak",explanation:"怎么 (zěnme) \xabn\xe4dip\xbb manysyny ber\xfd\xe4r \xfda-da bir zadyň usulyny sora\xfdar.",examples:["Bu harpy n\xe4dip \xfdazmaly?","Otly menziline n\xe4dip barmaly?"]},20:{title:"为什么 bilen 'n\xe4me \xfc\xe7in' soramak",explanation:"为什么 (w\xe8ish\xe9nme) \xabn\xe4me \xfc\xe7in\xbb manysyny ber\xfd\xe4r.",examples:["Sen n\xe4me \xfc\xe7in şatsyz?","Ol n\xe4me \xfc\xe7in gelmedi?"]},21:{title:"哪个 bilen 'ha\xfdsy' soramak",explanation:"哪个 (nǎ ge) \xabha\xfdsy biri\xbb manysyny ber\xfd\xe4r.",examples:["Ha\xfdsyny hala\xfdarsyň?","Ha\xfdsy seniňki?"]},22:{title:"几 bilen 'n\xe4\xe7e' soramak",explanation:"几 (jǐ) az san (10-dan az) garaşylanda \xabn\xe4\xe7e\xbb di\xfdip sora\xfdar.",examples:["N\xe4\xe7e \xe7agaň bar?","Sagat n\xe4\xe7e?"]},23:{title:"多少 bilen 'n\xe4\xe7e/n\xe4\xe7er\xe4k' soramak",explanation:"多少 (duōshǎo) \xe7\xe4ksiz \xabn\xe4\xe7e\xbb manysyny ber\xfd\xe4r.",examples:["Bu n\xe4\xe7e manat?","Telefon belgiň n\xe4\xe7e?"]},24:{title:"怎么样 bilen hil soramak",explanation:"怎么样 (zěnmey\xe0ng) \xabn\xe4hili?\xbb manysyny ber\xfd\xe4r — pikir, \xfdagda\xfd \xfc\xe7in.",examples:["Howa n\xe4hili?","Bu kitap n\xe4hili?"]},25:{title:"多 bilen dereje soramak",explanation:"多 (duō) sypatyň \xf6ň\xfcnde derej\xe4ni sora\xfdar — n\xe4\xe7e uly, n\xe4\xe7e k\xf6ne we ş.m.",examples:["\xddaşyň n\xe4\xe7e?","Ol n\xe4\xe7e uzakda?"]},26:{title:"了吗 bilen soraglar",explanation:"了吗 garaşyl\xfdan hereketiň tamamlanandygyny sora\xfdar.",examples:["Nahar i\xfddiňmi?","Ol gitdimi?"]},27:{title:"也 bilen 'hem'",explanation:"也 (yě) \xabhem\xbb \xfda-da \xab-da/-de\xbb manysyny ber\xfd\xe4r. Işlikden \xf6ň gel\xfd\xe4r, hi\xe7 ha\xe7an soňunda d\xe4l.",examples:["Men hem talyp.","Ol hem kino g\xf6rmegi hala\xfdar."]},28:{title:"都 bilen 'hemmesi'",explanation:"都 (dōu) \xabhemmesi\xbb \xfda-da \xabikisi-de\xbb manysyny ber\xfd\xe4r. Işlikden \xf6ň gel\xfd\xe4r we e\xfd\xe4 salgylan\xfdar.",examples:["Biz hemm\xe4miz hyta\xfdly.","Olaryň hemmesi geldi.","Bularyň hemmesini hala\xfdaryn."]},29:{title:"太…了 bilen 'aşa/gaty'",explanation:"太…了 (t\xe0i…le) \xabgaty\xbb \xfda-da \xabaşa\xbb manysyny ber\xfd\xe4r — artykma\xe7lygy \xfda-da g\xfc\xfd\xe7li du\xfdgyny aňlad\xfdar.",examples:["Gaty gowy!","Bu gaty gymmat.","Bu g\xfcn gaty yssy."]},30:{title:"有点儿 bilen 'azajyk'",explanation:"有点儿 (yǒudiǎnr) \xabazajyk\xbb manysyny ber\xfd\xe4r, k\xf6plen\xe7 islenilme\xfd\xe4n zady aňlad\xfdar.",examples:["Men azajyk \xfdadaw.","Bu g\xfcn azajyk sowuk."]},31:{title:"再 bilen geljekde '\xfdene'",explanation:"再 (z\xe0i) geljekd\xe4ki \xfda-da \xe7akla\xfdyş hereketleri \xfc\xe7in \xab\xfdene\xbb manysyny ber\xfd\xe4r.",examples:["Hoş gal! (\xddene g\xf6r\xfcşeris)","Ha\xfdyş, \xfdene bir gezek a\xfddyň."]},32:{title:"还 bilen 'entek/heniz'",explanation:"还 (h\xe1i) \xabentek\xbb manysyny ber\xfd\xe4r, hereketiň dowam ed\xfd\xe4ndigini \xfda-da goşma\xe7a bir zadyň bardygyny aňlad\xfdar.",examples:["Ol entek \xfdatyr.","\xddene n\xe4me isle\xfd\xe4rsiň?"]},33:{title:"还 + oňyn sypat bilen \xf6l\xe7egli baha",explanation:"还 oňyn sypatyň \xf6ň\xfcnde \xaberbet d\xe4l\xbb \xfda-da \xabbol\xfdar\xbb manysyny ber\xfd\xe4r — \xfdyly oňyn baha.",examples:["Tagamy erbet d\xe4l.","Bol\xfdar-la."]},34:{title:"在 bilen \xfderleşiş (bolmak)",explanation:"在 (z\xe0i) işlik h\xf6km\xfcnde \xabbir \xfderde bolmak\xbb manysyny ber\xfd\xe4r.",examples:["Ol \xf6\xfdde.","Meniň telefonum stoluň \xfcst\xfcnde."]},35:{title:"在 bilen bir \xfderde hereket etmek",explanation:"在 \xfder s\xf6z\xfcniň \xf6ň\xfcnde hereketiň nirede bol\xfdandygyny g\xf6rkez\xfd\xe4r.",examples:["Men mekdepde oka\xfdaryn.","Olar restoranda nahar i\xfd\xfd\xe4rler."]},36:{title:"想 bilen 'islemek'",explanation:"想 (xiǎng) \xabisle\xfd\xe4rin\xbb \xfda-da \xabisl\xe4rdim\xbb manysyny ber\xfd\xe4r.",examples:["Men \xe7a\xfd i\xe7mek isle\xfd\xe4rin.","Nir\xe4 gitmek isle\xfd\xe4rsiň?","Men işlemek isleme\xfd\xe4rin."]},37:{title:"能 bilen ukyp/m\xfcmkin\xe7ilik",explanation:"能 (n\xe9ng) ukyby \xfda-da m\xfcmkin\xe7iligi aňlad\xfdar — \xfdagda\xfdlara g\xf6r\xe4 \xabbil\xfd\xe4rin/başar\xfdaryn\xbb.",examples:["Gelip bilersiňmi?","Men bu g\xfcn gidip bilme\xfd\xe4rin."]},38:{title:"会 bilen \xf6wrenilen başarnyk",explanation:"会 (hu\xec) \xf6wrenilen ukyby aňlad\xfdar — n\xe4dip etmegi bil\xfd\xe4n zadyňyz.",examples:["Sen hyta\xfd\xe7a g\xfcrl\xe4p bil\xfd\xe4rsiňmi?","Ol nahar bişirip bil\xfd\xe4r.","Men maşyn s\xfcr\xfcp bilme\xfd\xe4rin."]},39:{title:"对 bilen işlikleri ulanmak",explanation:"对 (du\xec) \xab-a/e garşy\xbb \xfda-da \xab-a/e\xbb manysyny ber\xfd\xe4r — hereketiň nyşanasyny g\xf6rkez\xfd\xe4r.",examples:["Ol maňa gaty gowy.","Mugallym okuw\xe7ylara a\xfdd\xfdar."]},40:{title:"一下 bilen gysga\xe7a synap g\xf6rmek",explanation:"一下 (y\xedxi\xe0) işligi \xfdumşad\xfdar — \xabazajyk\xbb \xfda-da \xabgysga\xe7a\xbb.",examples:["Ha\xfdyş, azajyk garaşyň.","Bir seredeliň.","Synap g\xf6r."]},41:{title:"完 netije \xfcst\xfcnligi bilen tamamlamak",explanation:"完 (w\xe1n) netije \xfcst\xfcnligi h\xf6km\xfcnde \xabtamamlamak\xbb manysyny ber\xfd\xe4r.",examples:["Men i\xfdip boldum.","Bu kitaby okap gutardyňmy?"]},42:{title:"一起 bilen 'bile/bilelikde'",explanation:"一起 (y\xecqǐ) \xabbilelikde\xbb manysyny ber\xfd\xe4r.",examples:["Geliň bilelikde nahar i\xfdeliň.","Bile gitmek isle\xfd\xe4rsiňmi?"]},43:{title:"了 bilen tamamlanan hereket",explanation:"了 (le) işlikden soň hereketiň tamamlanandygyny belle\xfd\xe4r.",examples:["Men bir kitap satyn aldym.","Ol gitdi.","I\xfddiňmi?"]},44:{title:"了 bilen t\xe4ze \xfdagda\xfd",explanation:"S\xf6zlemiň soňundaky 了 \xfdagda\xfdyň \xfc\xfdtgemegini g\xf6rkez\xfd\xe4r — bir zat indi başga.",examples:["\xddagyş \xfdagdy.","Men a\xe7 (indi).","Bahar geldi."]},45:{title:"在 bilen dowam ed\xfd\xe4n hereket",explanation:"在 \xfda-da 正在 işlikden \xf6ň hereketiň h\xe4zir bolup ge\xe7\xfd\xe4ndigini aňlad\xfdar.",examples:["Ol telewizor g\xf6r\xfd\xe4r.","Men h\xe4zir hyta\xfd dilini \xf6wren\xfd\xe4rin.","Ejem nahar bişir\xfd\xe4r."]},46:{title:"吧 bilen \xfdumşatmak",explanation:"吧 (ba) s\xf6zlemi \xfdumşad\xfdar \xfda-da teklip ber\xfd\xe4r — \xabgeliň\xbb \xfda-da \xab-dyr \xf6\xfdd\xfd\xe4rin\xbb.",examples:["Gideliň.","Bol\xfdar-da.","Sen mugallym, şe\xfdlemi?"]},47:{title:"的时候 bilen 'ha\xe7an/wagty'",explanation:"的时候 (de sh\xedh\xf2u) \xab-anda/-\xe4nde\xbb \xfda-da \xabwagty\xbb manysyny ber\xfd\xe4r.",examples:["Nahar i\xfd\xfd\xe4rk\xe4ň g\xfcrl\xe4me.","\xddagyş \xfdaganda men \xf6\xfdde bol\xfdaryn."]},48:{title:"什么…都/也 bilen 'hemmesi/hi\xe7 zat'",explanation:"什么都 \xfda-da 什么也 \xabhemmesini\xbb \xfda-da \xabhi\xe7 zady\xbb (kontekste g\xf6r\xe4) aňlad\xfdar.",examples:["Ol hemme zady i\xfd\xfd\xe4r.","Men hi\xe7 zat etmek isleme\xfd\xe4rin."]},49:{title:"Wagt s\xf6z\xfcniň \xfderleşişi",explanation:"Wagt s\xf6zleri e\xfdeden \xf6ň \xfda-da soň bolup biler — ikisi-de dogry.",examples:["Men ertir giderin.","D\xfc\xfdn men gelmedim."]},50:{title:"以后 bilen 'soň'",explanation:"以后 (yǐh\xf2u) wagt \xfda-da wakadan \xabsoň\xbb manysyny ber\xfd\xe4r.",examples:["Nahardan soň gezm\xe4ge gideliň.","Sagat 3-den soň boş."]},51:{title:"以前 bilen '\xf6ň'",explanation:"以前 (yǐqi\xe1n) wagt \xfda-da wakadan \xab\xf6ň\xbb manysyny ber\xfd\xe4r.",examples:["Hyta\xfda gelm\xe4nk\xe4m, hyta\xfd\xe7a g\xfcrl\xe4p bilme\xfd\xe4rdim.","\xddatmazdan \xf6ň dişiňi \xfduwmaly."]},52:{title:"Sene gurluşy",explanation:"Seneler uludan ki\xe7\xe4 gid\xfd\xe4r: \xfdyl, a\xfd, g\xfcn.",examples:["2025-nji \xfdylyň 1-nji \xfdanwary","Doglan g\xfcn\xfcň ha\xe7an?"]},53:{title:"Wagt gurluşy (sagat)",explanation:"Wagty 点 (diǎn) sagat we 分 (fēn) minut bilen a\xfdd\xfdarlar.",examples:["H\xe4zir 3:30.","Sapagym sagat 8-de başla\xfdar."]},54:{title:"个 sanalyş s\xf6zi",explanation:"个 (g\xe8) iň k\xf6p ulanyl\xfdan sanalyş s\xf6zi. Belli bir sanalyş s\xf6z\xfcni bilmeseňiz, 个 ulanyň.",examples:["bir adam","\xfc\xe7 alma","n\xe4\xe7e talyp"]},55:{title:"岁 bilen \xfdaş",explanation:"岁 (su\xec) \xfdaş \xfc\xe7in sanalyş s\xf6zi — işlik gerek d\xe4l.",examples:["Men 20 \xfdaşymda.","Onuň gyzy 5 \xfdaşynda."]},56:{title:"Pul sanamak",explanation:"块 (ku\xe0i) \xfduanyň gepleşik s\xf6zi, 毛 (m\xe1o) onlugyň.",examples:["10 \xfduan","3,5 \xfduan"]},57:{title:"第 bilen tertip sanlar",explanation:"第 (d\xec) sany tertip sanyna \xf6w\xfcr\xfd\xe4r — birinji, ikinji, \xfc\xe7\xfcnji we ş.m.",examples:["birinji","\xfc\xe7\xfcnji adam","Bu meniň Hyta\xfda ilkinji gelişim."]},58:{title:"一些 bilen 'birn\xe4\xe7e'",explanation:"一些 (y\xecxiē) \xabbirn\xe4\xe7e\xbb \xfda-da \xabk\xe4bir\xbb manysyny ber\xfd\xe4r.",examples:["Meniň birn\xe4\xe7e soragym bar.","Maňa biraz suw ber."]},59:{title:"可以 bilen rugsat",explanation:"可以 (kěyǐ) rugsady (\xabbol\xfdar\xbb) \xfda-da m\xfcmkin\xe7iligi aňlad\xfdar. Ink\xe4ri — 不可以 (bolma\xfdar).",examples:["Girsem bol\xfdarmy?","Bu \xfderde \xe7ilim \xe7ekmek bolanok."]},60:{title:"比 bilen deňeşdirmek",explanation:"比 (bǐ) iki zady deňeşdir\xfd\xe4r. 比 soňundaky sypat bilen 很 ulanylma\xfdar.",examples:["Ol menden uzyn.","Bu g\xfcn d\xfc\xfdnden sowuk.","Hyta\xfd dili iňlis dilinden kyn."]},61:{title:"一样 bilen 'meňzeş' aňlatmak",explanation:"一样 (y\xedy\xe0ng) \xabmeňzeş\xbb manysyny ber\xfd\xe4r. Deňeşdiril\xfd\xe4n iki zady 跟 \xfda-da 和 bilen baglanyşdyr\xfdar.",examples:["Men seniň \xfdaly uzyn.","Bu şol bilen meňzeş.","Onuň telefony meniňki bilen meňzeş."]},62:{title:"最 bilen iň \xfdokary dereje",explanation:"最 (zu\xec) \xabiň\xbb manysyny ber\xfd\xe4r. Sypatyň \xfda-da işligiň g\xf6ni \xf6ň\xfcnde dur\xfdar.",examples:["Ol iň owadan.","Men hyta\xfd naharyny iň k\xf6p hala\xfdaryn.","Bu iň arzan."]},63:{title:"更 bilen 'has-da' aňlatmak",explanation:"更 (g\xe8ng) \xabhas-da\xbb manysyny ber\xfd\xe4r. Garaşylandan \xfdokary derej\xe4ni nygta\xfdar.",examples:["Ertir has-da sowuk bolar.","Men has-da gowy iş tapmak isle\xfd\xe4rin.","Ol menden has-da uzyn."]},64:{title:"一点儿 bilen 'azajyk has' aňlatmak",explanation:"一点儿 (y\xecdiǎnr) deňeşdirmeden soň \xabazajyk has\xbb manysyny ber\xfd\xe4r. K\xf6plen\xe7 比 bilen \xfda-da ha\xfdyşlarda ulanyl\xfdar.",examples:["Ha\xfdyş, azajyk ha\xfdalrak g\xfcrl\xe4ň.","Bu şondan azajyk uly.","Azajyk arzanladyň."]},65:{title:"因为…所以 bilen seb\xe4p we netije",explanation:"因为 (yīnw\xe8i) \xabseb\xe4bi\xbb we 所以 (suǒyǐ) \xabşonuň \xfc\xe7in\xbb manysyny ber\xfd\xe4r. Birini \xfda-da ikisini-de ulanyp bol\xfdar.",examples:["\xddagyş \xfdagany \xfc\xe7in gitmedim.","Ol syrkaw bolany \xfc\xe7in sapaga gelmedi.","Men \xfdadaw, şonuň \xfc\xe7in dyn\xe7 almak isle\xfd\xe4rin."]},66:{title:"虽然…但是 bilen gapma-garşylyk",explanation:"虽然 (suīr\xe1n) \xabher n\xe4\xe7e-de\xbb we 但是 (d\xe0nsh\xec) \xab\xfd\xf6ne\xbb manysyny ber\xfd\xe4r. Gapma-garşylyk ikinji bol\xfdar.",examples:["Her n\xe4\xe7e gymmat bolsa-da, tagamly.","Her n\xe4\xe7e meşgul bolsa-da, ol \xfdene geldi.","Her n\xe4\xe7e kyn bolsa-da, synap g\xf6rmek isle\xfd\xe4rin."]},67:{title:"除了…以外 bilen '-dan başga' aňlatmak",explanation:"除了…以外 (ch\xfale…yǐw\xe0i) \xab-dan başga\xbb \xfda-da \xab-den daşary\xbb manysyny ber\xfd\xe4r. 都 a\xfdyr\xfdar, 也/还 goş\xfdar.",examples:["Ondan başga hemm\xe4miz gitdik.","Hyta\xfd dilinden başga, ol iňlis\xe7e-de bil\xfd\xe4r."]},68:{title:"还是 we 或者 bilen '\xfda-da' aňlatmak",explanation:"还是 (h\xe1ishi) sa\xfdlaw teklip ed\xfd\xe4n soraglarda ulanyl\xfdar. 或者 (hu\xf2zhě) be\xfdan s\xf6zlemlerinde ulanyl\xfdar.",examples:["\xc7a\xfd i\xe7jekmi \xfda-da kofe?","Ertir \xfda-da birig\xfcn bol\xfdar.","Awtobusa m\xfcn\xfd\xe4rsiňmi \xfda-da metroya?"]},69:{title:"不但…而且 bilen 'diňe…d\xe4l, e\xfdsem-de' aňlatmak",explanation:"不但 (b\xfad\xe0n) \xabdiňe…d\xe4l\xbb we 而且 (\xe9rqiě) \xabe\xfdsem-de\xbb manysyny ber\xfd\xe4r. B has g\xfc\xfd\xe7li nokat.",examples:["Ol diňe hyta\xfd\xe7a g\xfcrl\xe4p bilm\xe4n, e\xfdsem gaty gowy g\xfcrle\xfd\xe4r.","Bu \xfder diňe owadan d\xe4l, e\xfdsem gaty asuda-da."]},70:{title:"已经…了 bilen 'e\xfd\xfd\xe4m' aňlatmak",explanation:"已经 (yǐjīng) \xabe\xfd\xfd\xe4m\xbb manysyny ber\xfd\xe4r. Soňundaky 了 \xfdagda\xfdyň \xfc\xfdtgemegini tassykla\xfdar.",examples:["Men e\xfd\xfd\xe4m i\xfddim.","Ol e\xfd\xfd\xe4m gitdi.","Film e\xfd\xfd\xe4m başlady."]},71:{title:"刚 we 刚才 bilen '\xfdaňy' aňlatmak",explanation:"刚 (gāng) \xab\xfdaňy\xbb manysyny ber\xfd\xe4r we işlikden \xf6ň gel\xfd\xe4r. 刚才 (gāngc\xe1i) \xab\xfdaňyja\xbb manysyny ber\xfd\xe4r.",examples:["Men \xfdaňy geldim.","Ol \xfdaňyja saňa jaň etdi.","Ol \xfdaňy nahar i\xfdip gutardy."]},72:{title:"终于 bilen 'ahyrsoňy' aňlatmak",explanation:"终于 (zhōngy\xfa) \xabahyrsoňy\xbb manysyny ber\xfd\xe4r. Bir zadyň uzak garaşylandan soň bolandygyny aňlad\xfdar.",examples:["Sen ahyrsoňy geldiň!","Men ahyrsoňy tapdym.","\xddagyş ahyrsoňy durdy."]},73:{title:"常常 we 经常 bilen 'k\xf6p/\xfdygy-\xfdygydan' aňlatmak",explanation:"常常 (ch\xe1ngch\xe1ng) we 经常 (jīngch\xe1ng) ikisi-de \xabk\xf6p\xbb manysyny ber\xfd\xe4r. K\xf6p \xfdagda\xfdlarda \xe7alşyp bol\xfdar.",examples:["Men şol restoranda k\xf6p bol\xfdaryn.","Ol k\xf6p gij\xe4 gal\xfdar.","Ol maňa k\xf6p k\xf6mek ed\xfd\xe4r."]},74:{title:"一直 bilen 'hemişe/\xfczn\xfcksiz' aňlatmak",explanation:"一直 (y\xeczh\xed) \xabhemişe\xbb \xfda-da \xab\xfczn\xfcksiz\xbb manysyny ber\xfd\xe4r — togtamazdan dowam ed\xfd\xe4n hereket.",examples:["Men b\xfctin wagt saňa garaşdym.","Ol hemişe Pekinde \xfdaşady.","Ol hemişe z\xe4hmets\xf6\xfder."]},75:{title:"突然 bilen 'birden' aňlatmak",explanation:"突然 (tūr\xe1n) \xabbirden\xbb manysyny ber\xfd\xe4r. E\xfdeden \xf6ň \xfda-da işlikden \xf6ň bolup bil\xfd\xe4r.",examples:["Ol birden g\xfcrlemesini kesdi.","Birden \xfdagyş \xfdagdy.","Ol birden g\xfcldi."]},76:{title:"马上 bilen 'derrew' aňlatmak",explanation:"马上 (mǎsh\xe0ng) \xabderrew\xbb \xfda-da \xabh\xe4zir\xbb manysyny ber\xfd\xe4r.",examples:["Men h\xe4zir gel\xfd\xe4rin.","Film başlamaga az galdy.","Ol derrew ga\xfddyp geler."]},77:{title:"到 netije \xfcst\xfcnligi",explanation:"到 (d\xe0o) netije \xfcst\xfcnligi h\xf6km\xfcnde hereketiň nyşanasyna \xfdetendigini aňlad\xfdar — \xabtapmak\xbb, \xab\xfdetmek\xbb.",examples:["Men tapdym.","Sen eşitdiňmi?","Men ony g\xf6rd\xfcm."]},78:{title:"好 netije \xfcst\xfcnligi",explanation:"好 (hǎo) netije \xfcst\xfcnligi h\xf6km\xfcnde hereketiň dogry \xfda-da doly edilendigini aňlad\xfdar — \xabta\xfd\xfdar\xbb \xfda-da \xabgutardy\xbb.",examples:["Nahar ta\xfd\xfdar.","Sen ta\xfd\xfdarmy?","\xd6\xfd işi gutardy."]},79:{title:"来/去 ugur \xfcst\xfcnligi",explanation:"来 (l\xe1i) g\xfcrle\xfdj\xe4 tarap hereket; 去 (q\xf9) g\xfcrle\xfdjiden daş hereket. Esasy işlikden soň gel\xfd\xe4r.",examples:["Ol ylgap geldi (maňa tarap).","Ha\xfdyş, gir.","Ol \xe7ykyp gitdi."]},80:{title:"得/不 bilen m\xfcmkin\xe7ilik \xfcst\xfcnligi",explanation:"Işlik + 得 + \xfcst\xfcnlik \xabedip bil\xfd\xe4r\xbb manysyny ber\xfd\xe4r. Işlik + 不 + \xfcst\xfcnlik \xabedip bilme\xfd\xe4r\xbb manysyny ber\xfd\xe4r.",examples:["Men g\xf6r\xfcp bil\xfd\xe4rin.","Men (diňl\xe4p) d\xfcş\xfcnip bilme\xfd\xe4rin.","Şun\xe7a k\xf6p\xfcni i\xfdip gutaryp bilersiňmi?"]},81:{title:"得 bilen dereje \xfcst\xfcnligi",explanation:"得 (de) işlikden soň hereketiň n\xe4hili edilendiginiň suratlandyrmasyny getir\xfd\xe4r — usuly \xfda-da netijesini.",examples:["Ol gaty gowy g\xfcrle\xfd\xe4r.","Ol gaty \xe7alt ylga\xfdar.","Sen gaty ha\xfdal \xfdaz\xfdarsyň."]},82:{title:"把 gurluşy",explanation:"把 (bǎ) doldurgy\xe7y işlikden \xf6ňe getir\xfd\xe4r, oňa n\xe4me bolandygyny nygtamak \xfc\xe7in. Işligiň netijesiniň \xfda-da ugrunyň bolmagy gerek.",examples:["Ha\xfdyş, gapyny \xfdapyň.","Ol kitaby stoluň \xfcst\xfcnde go\xfddy.","Men \xf6\xfd işini gutardym."]},83:{title:"被 bilen edilgen habar",explanation:"被 (b\xe8i) edilgen habary belle\xfd\xe4r. E\xfde hereketiň t\xe4sirini al\xfdar. K\xf6plen\xe7 islenilme\xfd\xe4n zady aňlad\xfdar.",examples:["Meniň telefonum ogurlandy.","Torty ol i\xfddi.","Şol kitap biri tarapyndan alyndy."]},84:{title:"让 bilen 'rugsat bermek/etdirmek' aňlatmak",explanation:"让 (r\xe0ng) \xabrugsat bermek\xbb \xfda-da \xabbirine bir zat etdirmek\xbb manysyny ber\xfd\xe4r.",examples:["Ejem meni okatdyr\xfdar.","Maňa pikirlendir\xe4\xfd.","Mugallym bize g\xfcrleşm\xe4ge rugsat berme\xfd\xe4r."]},85:{title:"从…到 bilen '-den…-a \xe7enli' aňlatmak",explanation:"从 (c\xf3ng) \xab-den\xbb we 到 (d\xe0o) \xab-a \xe7enli\xbb manysyny ber\xfd\xe4r. Wagt we \xfder aralygy \xfc\xe7in ulanyl\xfdar.",examples:["Bu \xfderden mekdebe \xfdakyn.","Irden agşama \xe7enli.","Men Pekinden Şanha\xfda otla gitdim."]},86:{title:"向 we 往 bilen 'tarapa' aňlatmak",explanation:"向 (xi\xe0ng) we 往 (wǎng) ikisi-de \xabtarapa\xbb manysyny ber\xfd\xe4r. 往 fiziki ugur \xfc\xe7in has k\xf6p ulanyl\xfdar; 向 abstrakt nyşanalar \xfc\xe7in hem bol\xfdar.",examples:["\xd6ňe \xfd\xf6re.","\xc7epe \xf6wr\xfcl.","Ol maňa tarap \xfd\xf6redi."]},87:{title:"Goşa 了: dowam ed\xfd\xe4n dowamlylyk",explanation:"Iki 了 — biri işlikden soň, biri s\xf6zlemiň soňunda — hereketiň ge\xe7mişde başlandygyny we entek dowam ed\xfd\xe4ndigini aňlad\xfdar.",examples:["Men \xfc\xe7 \xfdyl b\xe4ri hyta\xfd dilini \xf6wren\xfd\xe4rin.","Ol iki sagat b\xe4ri garaş\xfdar.","Biz b\xe4ş \xfdyl b\xe4ri bu \xfderde \xfdaşa\xfdarys."]},88:{title:"Dowamlylyk aňlatmak",explanation:"Dowamlylyk işlikden soň gel\xfd\xe4r. Doldurgy\xe7 bar bolsa, işligi ga\xfdtala\xfdar \xfda-da doldurgy\xe7dan \xf6ň 的 goş\xfdar.",examples:["Men her g\xfcn iki sagat oka\xfdaryn.","Ol sekiz sagat \xfdatdy.","Men bir sagat kitap okadym."]},89:{title:"每 bilen \xfdygylyk aňlatmak",explanation:"每 (měi) \xabher\xbb manysyny ber\xfd\xe4r. 都 k\xf6plen\xe7 \xabhemmesi/her gezek\xbb nygtamak \xfc\xe7in goşul\xfdar.",examples:["Men her g\xfcn maşk ed\xfd\xe4rin.","Ol her hepde gid\xfd\xe4r.","Hemmeler geldi."]},90:{title:"一边…一边 bilen 'ed\xfd\xe4rk\xe4' aňlatmak",explanation:"一边…一边 (y\xecbiān…y\xecbiān) iki hereketiň bir wagtda edilmegini aňlad\xfdar.",examples:["Ol nahar i\xfdip, telewizor g\xf6r\xfd\xe4r.","Ol \xfd\xf6r\xe4p, telefonda g\xfcrleş\xfd\xe4r.","Men a\xfddym diňl\xe4p, oka\xfdaryn."]},91:{title:"为了 bilen maksat aňlatmak",explanation:"为了 (w\xe8ile) \xab-mak \xfc\xe7in\xbb manysyny ber\xfd\xe4r. Hereketiň maksadyny \xfda-da seb\xe4bini a\xfdd\xfdar.",examples:["Hyta\xfd dilini \xf6wrenmek \xfc\xe7in Hyta\xfda geldim.","Ol synag \xfc\xe7in oka\xfdar.","Saglygyňyz \xfc\xe7in k\xf6pr\xe4k maşk etmeli."]},92:{title:"看 bilen 'bagly' aňlatmak",explanation:"看 (k\xe0n) \xab-a bagly\xbb manysyny berip bil\xfd\xe4r. 看 soňundaky s\xf6zlem netijesiniň n\xe4m\xe4 baglydygyny g\xf6rkez\xfd\xe4r.",examples:["Howa bagly-da.","Nir\xe4 gitmek isle\xfd\xe4ndigiňe bagly.","Gidip-gitmejegim \xfdagda\xfda bagly."]},93:{title:"着 bilen dowam ed\xfd\xe4n \xfdagda\xfd",explanation:"着 (zhe) hereketiň netijesinde d\xf6r\xe4n \xfdagda\xfdyň dowam ed\xfd\xe4ndigini g\xf6rkez\xfd\xe4r — hereket boldy we \xfdagda\xfd gal\xfdar.",examples:["Gapy a\xe7yk dur.","Ol dik dur.","Diwarda bir surat asylyp dur."]}}}}]);